'use strict';
const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),assert=require('node:assert/strict');
const root=path.resolve(__dirname,'..'),box={};vm.createContext(box);vm.runInContext(fs.readFileSync(path.join(root,'static/ui/stock-preparation-completion-recovery.js'),'utf8'),box);
const api=box.ERPStockCompletionRecovery,results=[],selected=process.argv.indexOf('--filter'),filter=selected>=0?new RegExp(process.argv[selected+1]):null;
function memory(){const map=new Map();return{get length(){return map.size},key:i=>[...map.keys()][i]??null,getItem:k=>map.get(k)??null,setItem:(k,v)=>map.set(k,String(v)),removeItem:k=>map.delete(k),map}}
function record(key='original-A',receiptId=11,actorId=7){return{schema:'stock-completion-local-v1',actorId,key,receiptId,endpoint:'/api/production/stock-preparation/'+receiptId+'/actions',body:{action:'complete',operation_key:key,expected_actor_id:actorId,job_id:17,actual_input_quantity:20,actual_output:20},summary:{code:'P23',name:'合成加工子件',source:'三楼A1',location:'三楼B2',inputUnit:'张',outputUnit:'只'},state:'prepared',hadUnknown:false,createdAt:'2026-10-10T00:00:00Z'}}
function test(name,fn){if(filter&&!filter.test(name))return;try{fn();results.push({name,passed:true})}catch(e){results.push({name,passed:false,error:e.stack})}}
test('写前读回且不持有调用方可变body',()=>{const storage=memory(),store=api.createStore(storage,7),r=record();store.write(r);r.body.actual_input_quantity=99;assert.equal(store.list()[0].body.actual_input_quantity,20)});
test('刷新恢复原body和同receipt锁，另一receipt不锁',()=>{const storage=memory();api.createStore(storage,7).write({...record(),state:'unknown',hadUnknown:true});const restored=api.createStore(storage,7);assert.equal(restored.blocked(11),true);assert.equal(restored.blocked(12),false);assert.equal(restored.list()[0].body.operation_key,'original-A')});
test('同账号双实例原请求独立键不覆盖',()=>{const storage=memory(),a=api.createStore(storage,7),b=api.createStore(storage,7);a.write(record('A',11));b.write(record('B',12));assert.equal(a.list().length,2);assert.equal(b.list().length,2)});
test('跨账号不读取或清另一账号记录',()=>{const storage=memory(),a=api.createStore(storage,7),b=api.createStore(storage,8);a.write(record());assert.equal(b.list().length,0);assert.throws(()=>b.remove(record()));assert.equal(a.list().length,1)});
test('同key异body或曾未知降级均保留原记录',()=>{const storage=memory(),store=api.createStore(storage,7),r={...record(),state:'unknown',hadUnknown:true};store.write(r);assert.throws(()=>store.write({...r,body:{...r.body,actual_input_quantity:21}}));assert.throws(()=>store.write({...r,hadUnknown:false}));assert.equal(store.list()[0].body.actual_input_quantity,20)});
test('写入或读回异常不当保存成功',()=>{const storage=memory(),store=api.createStore(storage,7);storage.setItem=()=>{};assert.throws(()=>store.write(record()),/未可靠保存/);storage.setItem=()=>{throw Error('quota')};assert.throws(()=>store.write(record()),/quota/)});
test('未知不得删除，confirmed只删自己同body记录',()=>{const storage=memory(),store=api.createStore(storage,7),r={...record(),state:'unknown',hadUnknown:true};store.write(r);assert.throws(()=>store.remove(r));const done={...r,state:'confirmed'};store.write(done);store.write(record('B',12));store.remove(done);assert.equal(store.list().length,1);assert.equal(store.list()[0].key,'B')});
test('confirmed清理失败保留防重且不锁另一receipt',()=>{const storage=memory(),store=api.createStore(storage,7),r={...record(),state:'confirmed',hadUnknown:true};store.write(r);storage.removeItem=()=>{throw Error('remove failed')};assert.throws(()=>store.remove(r));assert.equal(store.blocked(11),true);assert.equal(store.blocked(12),false);assert.throws(()=>store.write({...r,state:'unknown'}));store.write(record('B',12));assert.equal(store.list().length,2)});
test('坏记录和枚举读取异常不能伪装无待核对',()=>{const storage=memory(),store=api.createStore(storage,7);storage.setItem(store.keyFor('A'),'{}');assert.throws(()=>store.list());storage.key=()=>{throw Error('storage blocked')};assert.throws(()=>store.list())});
