 function actualRow(sample){const source=JSON.parse(JSON.stringify(sample.sourceRow||REAL_HTTP['normal-partial'].sourceRow));return{...source,entry_type:'single_job',job:source.jobs.find(j=>j.id===sample.originalBody.job_id)}};
 async function prepareActual(sample){const c=context(),body=sample.originalBody,p=sample.write?.body?.completion_receipt||sample.resolve?.body?.completion_receipt;c.user={id:sample.actorId,role:'admin'};c.stockOperationKey=()=>body.operation_key;c.stockLocations=[{id:body.location_id,layout_version:body.layout_version,location_name:p?.location_name||'原实际货位'}];const r=actualRow(sample);await c.openStockDialog(r);const d=c.stockPrepDialog;d.location=body.location_id;d.inputQuantity=body.actual_input_quantity;d.job._actual=body.actual_output;d.disposition=body.output_kind;return c;}
 for(const name of ['normal-partial','normal-full','nullable-customer','units-frozen','independent-nullable']){
  const sample=REAL_HTTP[name];
  await check('真实HTTP首200由实际保存函数核完整proof/'+name,async()=>{const c=await prepareActual(sample);reply=sample.write.body;await c.saveStockDialog('complete');assert.equal(api.stable(posts[0].body),api.stable(sample.originalBody));assert.equal(c.stockPrepDialog,null);assert.equal(c.stockCompletionRows[0].state,'confirmed');assert.equal(c.stockCompletionRows[0].receipt.actual_output,sample.originalBody.actual_output);assert.equal(c.stockCompletionStore().list().length,0);assert.equal(events.length,1)});
  await check('真实HTTP resolve由刷新页面实际加载核对零业务POST/'+name,async()=>{const c=await prepareActual(sample);await c.saveStockDialog('complete');const before=posts.filter(p=>p.url.endsWith('/actions')).length,stored=api.stable(c.stockCompletionStore().list()[0].body),fresh=context();fresh.user={id:sample.actorId,role:'admin'};await fresh.loadStockPreparation(1);const r=fresh.stockCompletionRows[0];assert.equal(api.stable(r.body),stored);assert.equal(fresh.stockCompletionLocked(actualRow(sample)),true);reply=sample.resolve.body;await fresh.resolveStockCompletion(r);assert.equal(r.state,'confirmed');assert.equal(r.receipt.actual_input_quantity,sample.originalBody.actual_input_quantity);assert.equal(posts.filter(p=>p.url.endsWith('/actions')).length,before);assert.equal(fresh.stockCompletionStore().list().length,0);assert.equal(fresh.stockCompletionRows.length,1)});
 }
 await check('真实提交后丢ack500→新页面真实GET/continuation→readonly completed零新增保存',async()=>{const s=REAL_HTTP['committed-ack-loss'],c=await prepareActual(s);postError={response:{status:s.write.status,data:s.write.body,headers:s.write.headers}};await c.saveStockDialog('complete');const original=api.stable(c.stockCompletionRows[0].body),key=c.stockCompletionRows[0].key;assert.equal(c.stockCompletionRows[0].state,'unknown');const fresh=context();fresh.user={id:s.actorId,role:'admin'};getReply=async url=>({data:url===s.resolve.body.trace_url?s.trace.body:s.workspaceAfterLoss.body});await fresh.loadStockPreparation(1);const continuation=fresh.stockPrepRows.find(r=>r.receipt_item_id===s.receiptId);assert.equal(continuation.job.id,s.resolve.body.completion_receipt.continuation_job_id);await fresh.openStockDialog(continuation);assert.equal(fresh.stockPrepDialog.inputQuantity,8);assert.equal(fresh.stockCompletionLocked(fresh.stockPrepDialog.row),true);await fresh.saveStockDialog('complete');assert.equal(posts.filter(p=>p.url.endsWith('/actions')).length,1);postError=null;reply=s.resolve.body;await fresh.resolveStockCompletion(fresh.stockCompletionRows[0]);assert.equal(posts.filter(p=>p.url.endsWith('/actions')).length,1);const resolvePost=posts.find(p=>p.url.endsWith('/completion-result'));assert.equal(resolvePost.body.operation_key,key);assert.equal(api.stable(resolvePost.body.original_request),original);assert.equal(fresh.stockCompletionRows[0].state,'confirmed');assert.equal(fresh.stockCompletionRows[0].receipt.actual_output,8);assert.equal(fresh.stockCompletionStore().list().length,0);await fresh.viewStockCompletionTrace(fresh.stockCompletionRows[0]);assert.equal(fresh.stockPrepDialog.view,'history');assert.ok(fresh.stockPrepDialog.row.jobs.some(j=>j.id===s.resolve.body.completion_receipt.completed_job_id&&j.actual_output===8));assert.equal(posts.filter(p=>p.url.endsWith('/actions')).length,1)});
 await check('真实legacy_trace原body/cache保留、有可读记录动作、无业务续写',async()=>{const s=REAL_HTTP['legacy-trace'],c=await prepareActual(s);await c.saveStockDialog('complete');reply=s.resolve.body;const r=c.stockCompletionRows[0];await c.resolveStockCompletion(r);assert.equal(r.state,'unknown');assert.equal(r.notRecorded,false);assert.equal(r.traceUrl,s.resolve.body.trace_url);assert.equal(c.stockCompletionStore().list().length,1);assert.equal(posts.filter(p=>p.url.endsWith('/actions')).length,1)});
